(function(){
'use strict';
if(typeof DATA==='undefined' || typeof PUBLIC_DATA==='undefined') return;
const S=v=>(v==null?'':String(v));
const N=v=>S(v).toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const K='кириллина светлана алексеевна';
const REL='история религии изучаемой страны (региона)';
const conflictGroups=new Set([
  '23б/п402-арабский/7',
  '23б/ф402-арабский/7',
  '23б/ф419-турецкий/7',
  '23б/и416-суахили/7'
]);

// 01.09.2026: по прямому уточнению восстановить именно Вт 13:00 у Кириллиной,
// ауд.228 сохранить. Ранее пара была ошибочно оставлена «уточняется».
for(let i=DATA.length-1;i>=0;i--){
  const r=DATA[i];
  if(r && N(r.teacher)===K && N(r.discipline).includes(REL)) DATA.splice(i,1);
}

// В этом же слоте в техническом своде висели ОВЯ у части потока Кириллиной.
// Снимаем только конкретные пересекающиеся строки Вт 13:00 у тех групп, которые
// входят в поток исламоведения. Остальные языковые пары недели не трогаем.
for(let i=DATA.length-1;i>=0;i--){
  const r=DATA[i];
  if(!r) continue;
  if(S(r.course).trim()==='4 бакалавриат' && r.day==='Вт' && r.time==='13:00' &&
     N(r.discipline).includes('основной восточный язык') && conflictGroups.has(N(r.group))){
    DATA.splice(i,1);
  }
}

DATA.push({
  group:'группа 23Б/Ист-311_арабский/5, группа 23Б/Ист-314_пушту/5, группа 23Б/Ист-315_суахили/5, группа 23Б/Ист-316_хауса/5, группа 23Б/Пл-341_арабский/5, группа23Б/Фл-321_арабский/5, группа23Б/Фл-323_персидский/5, группа23Б/Фл-324_турецкий/5',
  course:'3 бакалавриат',
  direction:'',
  day:'Вт',
  time:'13:00',
  discipline:'История религии изучаемой страны (региона) (Исламоведение) — лекции',
  extra:'2 акад. ч/нед.; совместное чтение; ведущая — С.А. Кириллина',
  teacher:'Кириллина Светлана Алексеевна',
  room_hint:'228',
  quality:'01.09.2026: исправление предыдущей правки. Пара Кириллиной не должна была уходить в «уточняется»: восстановлено исходное Вт 13:00. Ауд.228 сохранена по прямому указанию. Актуальная заявка подтверждает сам курс, 2 ч/нед., допустимые дни Вт/Пт и время 10:40/13:00/14:40/16:20. Чтобы снять реальную накладку потока, удалены только ОВЯ Вт 13:00 у входящих в этот поток групп 4 курса: арабисты-политологи, арабисты-филологи, филологи-туркологи и историки-суахили; их остальные языковые пары недели сохранены.'
});

const rows=typeof isServiceRow==='function'?DATA.filter(r=>!isServiceRow(r)):DATA.slice();
PUBLIC_DATA.splice(0,PUBLIC_DATA.length,...rows);
try{if(typeof buildGroupItems==='function')buildGroupItems();}catch(e){}
try{if(typeof buildBrowseList==='function')buildBrowseList();}catch(e){}
try{if(typeof showEmpty==='function')showEmpty();}catch(e){}
})();
